import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { BreachAnalytics } from '@/components/geofencing/BreachAnalytics'

vi.mock('@/lib/api/geofencing', () => ({
    getGeofenceAnalytics: vi.fn(),
}))

import { getGeofenceAnalytics } from '@/lib/api/geofencing'

const mockAnalyticsResponse = {
    data: {
        geofence_id: 1,
        geofence_name: 'Warehouse Alpha',
        analytics_period_days: 30,
        summary: {
            total_breaches: 12,
            breach_rate_per_day: 0.4,
            most_active_vehicle: { vehicle_id: 5, registration: 'LND-123-XY', breach_count: 4 },
            peak_breach_time: '18:00-20:00',
            average_dwell_time_minutes: 145,
        },
        timeline: [
            { date: '2026-03-03', day_of_week: 'Monday', breach_count: 2, unique_vehicles: 1 },
            { date: '2026-03-04', day_of_week: 'Tuesday', breach_count: 5, unique_vehicles: 2 },
            { date: '2026-03-05', day_of_week: 'Wednesday', breach_count: 1, unique_vehicles: 1 },
            { date: '2026-03-06', day_of_week: 'Thursday', breach_count: 0, unique_vehicles: 0 },
            { date: '2026-03-07', day_of_week: 'Friday', breach_count: 3, unique_vehicles: 2 },
            { date: '2026-03-08', day_of_week: 'Saturday', breach_count: 1, unique_vehicles: 1 },
            { date: '2026-03-09', day_of_week: 'Sunday', breach_count: 0, unique_vehicles: 0 },
        ],
        vehicle_ranking: [
            { rank: 1, vehicle_id: 5, registration: 'LND-123-XY', breach_count: 4, breach_duration_avg_minutes: 12, last_breach: '2026-03-09T18:30:00Z' },
            { rank: 2, vehicle_id: 8, registration: 'ABJ-567-ZZ', breach_count: 3, breach_duration_avg_minutes: 5, last_breach: '2026-03-08T19:15:00Z' },
        ],
    },
}

function renderWithQuery(ui: React.ReactElement) {
    const qc = new QueryClient({ defaultOptions: { queries: { retry: false } } })
    return render(<QueryClientProvider client={qc}>{ui}</QueryClientProvider>)
}

beforeEach(() => {
    vi.clearAllMocks()
    vi.mocked(getGeofenceAnalytics).mockResolvedValue(mockAnalyticsResponse as any)
})

describe('BreachAnalytics', () => {
    it('does not render when isOpen=false', () => {
        const { container } = renderWithQuery(
            <BreachAnalytics isOpen={false} onClose={vi.fn()} geofenceId="1" />
        )
        expect(container.firstChild).toBeNull()
    })

    it('renders modal header when open', () => {
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="1" geofenceName="Warehouse Alpha" />)
        expect(screen.getByText('Breach')).toBeInTheDocument()
        expect(screen.getByText(/Warehouse Alpha/)).toBeInTheDocument()
    })

    it('shows loading spinner initially', () => {
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="1" />)
        expect(screen.getByText(/Loading breach data/)).toBeInTheDocument()
    })

    it('renders KPI stats from API response', async () => {
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="1" />)
        await waitFor(() => expect(screen.getByText('12')).toBeInTheDocument())
        expect(screen.getByText('145m')).toBeInTheDocument()
        expect(screen.getByText('18:00-20:00')).toBeInTheDocument()
    })

    it('renders vehicle ranking list', async () => {
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="1" />)
        await waitFor(() => screen.getByText('LND-123-XY'))
        expect(screen.getByText('ABJ-567-ZZ')).toBeInTheDocument()
    })

    it('calls onClose when close button clicked', async () => {
        const onClose = vi.fn()
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={onClose} geofenceId="1" />)
        await waitFor(() => screen.getByText('12'))
        fireEvent.click(screen.getByRole('button', { name: /CLOSE ANALYSIS/i }))
        expect(onClose).toHaveBeenCalled()
    })

    it('calls getGeofenceAnalytics with correct params', async () => {
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="42" />)
        await waitFor(() => expect(getGeofenceAnalytics).toHaveBeenCalledWith('42', {
            days: 30,
            include_timeline: true,
            include_ranking: true,
        }))
    })

    it('shows empty offender message when vehicle_ranking is empty', async () => {
        vi.mocked(getGeofenceAnalytics).mockResolvedValue({
            ...mockAnalyticsResponse,
            data: { ...mockAnalyticsResponse.data, vehicle_ranking: [] },
        } as any)
        renderWithQuery(<BreachAnalytics isOpen={true} onClose={vi.fn()} geofenceId="1" />)
        await waitFor(() => screen.getByText('No offender data available'))
    })
})

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'
import { GeofenceList } from '@/components/geofencing/GeofenceList'

// Mock next/navigation
vi.mock('next/navigation', () => ({
    useRouter: () => ({ push: vi.fn() }),
}))

// Mock geofencing API
vi.mock('@/lib/api/geofencing', () => ({
    getGeofences: vi.fn(),
    deleteGeofence: vi.fn(),
}))

// Mock sonner toast
vi.mock('sonner', () => ({ toast: { success: vi.fn(), error: vi.fn() } }))

// Mock child modals to avoid Leaflet/complex deps
vi.mock('@/components/geofencing/BulkAssignmentModal', () => ({
    BulkAssignmentModal: ({ isOpen }: { isOpen: boolean }) =>
        isOpen ? <div data-testid="bulk-assignment-modal" /> : null,
}))
vi.mock('@/components/geofencing/BreachAnalytics', () => ({
    BreachAnalytics: ({ isOpen }: { isOpen: boolean }) =>
        isOpen ? <div data-testid="breach-analytics-modal" /> : null,
}))

import { getGeofences, deleteGeofence } from '@/lib/api/geofencing'

const mockGeofences = [
    {
        id: '1',
        attributes: { name: 'Warehouse Alpha', type: 'circle', alert_type: 'both', is_active: true, radius: 500 },
        relationships: { vehicles: { data: [{ id: '10' }, { id: '11' }] } },
    },
    {
        id: '2',
        attributes: { name: 'Depot Beta', type: 'polygon', alert_type: 'exit', is_active: false, radius: undefined },
        relationships: { vehicles: { data: [] } },
    },
]

function renderWithQuery(ui: React.ReactElement) {
    const qc = new QueryClient({ defaultOptions: { queries: { retry: false } } })
    return render(<QueryClientProvider client={qc}>{ui}</QueryClientProvider>)
}

beforeEach(() => {
    vi.clearAllMocks()
    vi.mocked(getGeofences).mockResolvedValue({
        message: 'OK',
        data: {
            geofences: mockGeofences as any,
            pagination: { current: 1, lastPage: 1, total: 2, perPage: 9, next_page_url: null, prev_page_url: null, from: 1 },
        },
    })
})

describe('GeofenceList', () => {
    it('renders loading skeletons initially', () => {
        renderWithQuery(<GeofenceList />)
        const skeletons = document.querySelectorAll('.animate-pulse')
        expect(skeletons.length).toBeGreaterThan(0)
    })

    it('renders geofence cards after load', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => expect(screen.getByText('Warehouse Alpha')).toBeInTheDocument())
        expect(screen.getByText('Depot Beta')).toBeInTheDocument()
    })

    it('shows correct vehicle count from relationships', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))
        // Warehouse Alpha has 2 vehicles
        const counts = screen.getAllByText('2')
        expect(counts.length).toBeGreaterThan(0)
    })

    it('shows active/inactive badges correctly', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('MONITORING ACTIVE'))
        expect(screen.getByText('INACTIVE')).toBeInTheDocument()
    })

    it('opens BulkAssignmentModal when ASSIGN is clicked', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))
        const assignButtons = screen.getAllByTitle('Assign vehicles')
        fireEvent.click(assignButtons[0])
        expect(screen.getByTestId('bulk-assignment-modal')).toBeInTheDocument()
    })

    it('opens BreachAnalytics modal when INSIGHTS is clicked', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))
        const insightButtons = screen.getAllByTitle('View breach analytics')
        fireEvent.click(insightButtons[0])
        expect(screen.getByTestId('breach-analytics-modal')).toBeInTheDocument()
    })

    it('shows delete confirmation dialog when DELETE is clicked', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))
        const deleteButtons = screen.getAllByTitle('Delete geofence')
        fireEvent.click(deleteButtons[0])
        expect(screen.getByText('Delete Geofence')).toBeInTheDocument()
        expect(screen.getByText(/Are you sure/)).toBeInTheDocument()
    })

    it('calls deleteGeofence API and closes dialog on confirm', async () => {
        vi.mocked(deleteGeofence).mockResolvedValue(undefined)
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))

        fireEvent.click(screen.getAllByTitle('Delete geofence')[0])
        await waitFor(() => screen.getByText('Delete Geofence'))

        const confirmBtn = screen.getByRole('button', { name: /Delete$/ })
        fireEvent.click(confirmBtn)

        await waitFor(() => expect(deleteGeofence).toHaveBeenCalledWith('1'))
    })

    it('shows empty state when no geofences returned', async () => {
        vi.mocked(getGeofences).mockResolvedValue({
            message: 'OK',
            data: { geofences: [], pagination: { current: 1, lastPage: 1, total: 0, perPage: 9, next_page_url: null, prev_page_url: null, from: 0 } },
        })
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('No Active Zones'))
    })

    it('shows custom empty state message when searchTerm provided', async () => {
        vi.mocked(getGeofences).mockResolvedValue({
            message: 'OK',
            data: { geofences: [], pagination: { current: 1, lastPage: 1, total: 0, perPage: 9, next_page_url: null, prev_page_url: null, from: 0 } },
        })
        renderWithQuery(<GeofenceList searchTerm="nonexistent" />)
        await waitFor(() => expect(screen.getByText(/No geofences match/)).toBeInTheDocument())
    })

    it('does not render pagination when only 1 page', async () => {
        renderWithQuery(<GeofenceList />)
        await waitFor(() => screen.getByText('Warehouse Alpha'))
        expect(screen.queryByText(/Page 1 of/)).toBeNull()
    })

    it('renders pagination when multiple pages exist', async () => {
        vi.mocked(getGeofences).mockResolvedValue({
            message: 'OK',
            data: {
                geofences: mockGeofences as any,
                pagination: { current: 1, lastPage: 3, total: 27, perPage: 9, next_page_url: null, prev_page_url: null, from: 1 },
            },
        })
        renderWithQuery(<GeofenceList />)
        await waitFor(() => expect(screen.getByText(/Page 1 of 3/)).toBeInTheDocument())
    })
})

/**
 * Geofence E2E-style flow tests
 * Covers complete user journeys using React Testing Library.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest'
import { render, screen, waitFor, fireEvent } from '@testing-library/react'
import { QueryClient, QueryClientProvider } from '@tanstack/react-query'

// ΓöÇΓöÇΓöÇ Next.js mocks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const mockPush = vi.fn()
vi.mock('next/navigation', () => ({
    useRouter: () => ({ push: mockPush }),
    useParams: () => ({ id: '1' }),
}))
vi.mock('next/dynamic', () => ({
    default: (_loader: () => Promise<any>, opts?: { loading?: () => React.ReactNode }) =>
        function DynamicComponent(_props: any) {
            return opts?.loading ? opts.loading() : null
        },
}))

// ΓöÇΓöÇΓöÇ API mocks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
vi.mock('@/lib/api/geofencing', () => ({
    getGeofences: vi.fn(),
    getGeofenceById: vi.fn(),
    createGeofence: vi.fn(),
    updateGeofence: vi.fn(),
    deleteGeofence: vi.fn(),
    getGeofenceVehicles: vi.fn(),
    bulkAssignVehicles: vi.fn(),
    getGeofenceAnalytics: vi.fn(),
}))
vi.mock('@/lib/api/vehicles', () => ({
    getVehicles: vi.fn(),
}))

// ΓöÇΓöÇΓöÇ Subscription/Auth store mocks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
vi.mock('@/hooks/useSubscription', () => ({
    useSubscription: () => ({
        hasCapability: () => true,
        planTier: 'enterprise',
        planName: 'Enterprise',
        isPaymentOverdue: false,
        isGracePeriod: false,
        dunningStage: null,
    }),
}))
vi.mock('@/store/authStore', () => ({
    useAuthStore: (selector: any) =>
        selector({
            user: { id: 1, name: 'Admin', role: 'administrator', organization_id: 'org-1' },
            organization: { id: 1, identifier: 'acme', name: 'ACME', subdomain: 'acme', slug: null },
            token: 'test-token',
        }),
}))

// ΓöÇΓöÇΓöÇ Shared modal mocks (avoid Leaflet/chart deps in flow tests) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
vi.mock('@/components/geofencing/BulkAssignmentModal', () => ({
    BulkAssignmentModal: ({ isOpen, geofenceName, onClose }: any) =>
        isOpen ? (
            <div data-testid="bulk-modal">
                <p>Assigning to {geofenceName}</p>
                <button onClick={onClose}>Close Assign</button>
            </div>
        ) : null,
}))
vi.mock('@/components/geofencing/BreachAnalytics', () => ({
    BreachAnalytics: ({ isOpen, onClose }: any) =>
        isOpen ? (
            <div data-testid="breach-modal">
                <button onClick={onClose}>Close Analytics</button>
            </div>
        ) : null,
}))

// ΓöÇΓöÇΓöÇ Toast mock (hoisted so vi.mock factory can reference it) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const mockToast = vi.hoisted(() => ({ success: vi.fn(), error: vi.fn() }))
vi.mock('sonner', () => ({ toast: mockToast }))

// ΓöÇΓöÇΓöÇ Imports (after mocks) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
import { getGeofences, deleteGeofence } from '@/lib/api/geofencing'
import { GeofenceList } from '@/components/geofencing/GeofenceList'

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
function makeQC() {
    return new QueryClient({ defaultOptions: { queries: { retry: false }, mutations: { retry: false } } })
}
function wrap(ui: React.ReactElement, qc = makeQC()) {
    return render(<QueryClientProvider client={qc}>{ui}</QueryClientProvider>)
}

const mockGeofences = [
    {
        id: '1',
        attributes: { name: 'Main Depot', type: 'circle', alert_type: 'both', is_active: true, radius: 1000 },
        relationships: { vehicles: { data: [{ id: '10' }, { id: '11' }] } },
    },
    {
        id: '2',
        attributes: { name: 'Customer Site A', type: 'polygon', alert_type: 'exit', is_active: false, radius: undefined },
        relationships: { vehicles: { data: [] } },
    },
]

beforeEach(() => {
    vi.clearAllMocks()
    mockPush.mockClear()
    vi.mocked(getGeofences).mockResolvedValue({
        message: 'OK',
        data: {
            geofences: mockGeofences as any,
            pagination: { current: 1, lastPage: 1, total: 2, perPage: 9, next_page_url: null, prev_page_url: null, from: 1 },
        },
    })
})

// ΓöÇΓöÇΓöÇ FLOW 1: Delete geofence ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
describe('Flow: Delete geofence', () => {
    it('shows dialog ΓåÆ confirms ΓåÆ calls API ΓåÆ toast shown', async () => {
        vi.mocked(deleteGeofence).mockResolvedValue(undefined)
        wrap(<GeofenceList />)

        // Wait for list to load
        await waitFor(() => screen.getByText('Main Depot'))

        // Click delete on first geofence
        fireEvent.click(screen.getAllByTitle('Delete geofence')[0])

        // Confirmation dialog appears with the geofence name
        expect(screen.getByText('Delete Geofence')).toBeInTheDocument()
        expect(screen.getAllByText(/Main Depot/).length).toBeGreaterThan(0)

        // Cancel closes dialog
        fireEvent.click(screen.getByRole('button', { name: /Cancel/ }))
        expect(screen.queryByText('Delete Geofence')).toBeNull()

        // Re-open and confirm delete
        fireEvent.click(screen.getAllByTitle('Delete geofence')[0])
        fireEvent.click(screen.getByRole('button', { name: /^Delete$/ }))

        await waitFor(() => {
            expect(deleteGeofence).toHaveBeenCalledWith('1')
            expect(mockToast.success).toHaveBeenCalledWith('Geofence deleted successfully.')
        })
    })

    it('shows error toast when delete fails', async () => {
        vi.mocked(deleteGeofence).mockRejectedValue(new Error('Server error'))
        wrap(<GeofenceList />)

        await waitFor(() => screen.getByText('Main Depot'))
        fireEvent.click(screen.getAllByTitle('Delete geofence')[0])
        fireEvent.click(screen.getByRole('button', { name: /^Delete$/ }))

        await waitFor(() => expect(mockToast.error).toHaveBeenCalledWith('Failed to delete geofence.'))
    })
})

// ΓöÇΓöÇΓöÇ FLOW 2: Assign vehicles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
describe('Flow: Bulk assign vehicles', () => {
    it('opens modal for correct geofence ΓåÆ closes on dismiss', async () => {
        wrap(<GeofenceList />)
        await waitFor(() => screen.getByText('Main Depot'))

        // Click ASSIGN on first geofence
        fireEvent.click(screen.getAllByTitle('Assign vehicles')[0])

        // Modal should open with the correct geofence name
        const modal = screen.getByTestId('bulk-modal')
        expect(modal).toBeInTheDocument()
        expect(screen.getByText(/Assigning to Main Depot/)).toBeInTheDocument()

        // Close modal
        fireEvent.click(screen.getByText('Close Assign'))
        await waitFor(() => expect(screen.queryByTestId('bulk-modal')).toBeNull())
    })

