// ΓöÇΓöÇ Standardized Table Pagination ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface TablePaginationProps {
    pagination?: {
        current_page: number
        last_page: number
        total: number
    }
    onPageChange: (page: number) => void
    variant?: 'default' | 'simple'
}

function TablePagination({ pagination, onPageChange, variant = 'default' }: TablePaginationProps) {
    if (!pagination || pagination.last_page <= 1) return null

    if (variant === 'simple') {
        return (
            <div className="flex items-center justify-between pt-4">
                <p className="text-xs text-slate-500 font-medium">Page {pagination.current_page} of {pagination.last_page}</p>
                <div className="flex gap-2">
                    <Button
                        size="sm" variant="outline"
                        className="h-8 px-3 text-xs"
                        disabled={pagination.current_page <= 1}
                        onClick={() => onPageChange(pagination.current_page - 1)}
                    >
                        Previous
                    </Button>
                    <Button
                        size="sm" variant="outline"
                        className="h-8 px-3 text-xs"
                        disabled={pagination.current_page >= pagination.last_page}
                        onClick={() => onPageChange(pagination.current_page + 1)}
                    >
                        Next
                    </Button>
                </div>
            </div>
        )
    }

    return (
        <div className="flex items-center justify-between px-6 py-4 border-t border-slate-100 bg-slate-50/50">
            <p className="text-[11px] text-slate-500 font-bold uppercase tracking-widest">
                Page {pagination.current_page} of {pagination.last_page} &nbsp;┬╖&nbsp; {pagination.total} records
            </p>
            <div className="flex gap-2">
                <Button
                    size="sm" variant="outline"
                    className="h-8 px-3 text-xs font-bold uppercase tracking-wider"
                    disabled={pagination.current_page <= 1}
                    onClick={() => onPageChange(pagination.current_page - 1)}
                >
                    Previous
                </Button>
                <Button
                    size="sm" variant="outline"
                    className="h-8 px-3 text-xs font-bold uppercase tracking-wider"
                    disabled={pagination.current_page >= pagination.last_page}
                    onClick={() => onPageChange(pagination.current_page + 1)}
                >
                    Next
                </Button>
            </div>
        </div>
    )
}

// ΓöÇΓöÇ Account status badge ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function AccountStatusBadge({ status }: { status: FuelCardAccount['status'] }) {
    switch (status) {
        case 'active': return <Badge className="bg-emerald-100 text-emerald-800 border-none">ΓùÅ Active</Badge>
        case 'pending': return <Badge className="bg-amber-100 text-amber-800 border-none">ΓùÅ Pending</Badge>
        case 'suspended': return <Badge className="bg-rose-100 text-rose-800 border-none">ΓùÅ Suspended</Badge>
        case 'rejected': return <Badge className="bg-rose-100 text-rose-800 border-none">ΓùÅ Rejected</Badge>
    }
}

function CardStatusBadge({ status }: { status: string }) {
    switch (status) {
        case 'issued': return <Badge className="bg-emerald-100 text-emerald-800 border-none text-[10px]">Issued</Badge>
        case 'blocked': return <Badge className="bg-rose-100 text-rose-800 border-none text-[10px]">Blocked</Badge>
        default: return <Badge variant="outline" className="bg-amber-50 text-amber-700 border-amber-200 text-[10px]">Requested</Badge>
