'use client'

import React, { useEffect, useState } from 'react'
import { MapContainer, TileLayer, FeatureGroup, useMap } from 'react-leaflet'
import { EditControl } from 'react-leaflet-draw'
import * as L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import 'leaflet-draw/dist/leaflet.draw.css'
import { Geofence } from '@/types'

// Fix Leaflet icons issues with Next.js SSR
L.Icon.Default.mergeOptions({
    iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png').default,
    iconUrl: require('leaflet/dist/images/marker-icon.png').default,
    shadowUrl: require('leaflet/dist/images/marker-shadow.png').default,
})

interface GeofenceMapEditorProps {
    initialGeofence?: Geofence
    onChange: (data: { type: 'polygon' | 'circle', coordinates: any, radius?: number }) => void
    height?: string
}

export default function GeofenceMapEditor({ initialGeofence, onChange, height = '400px' }: GeofenceMapEditorProps) {
    const [mapReady, setMapReady] = useState(false)
    const DefaultPosition: [number, number] = [6.5244, 3.3792] // Lagos, Nigeria

    useEffect(() => {
        setMapReady(true)
    }, [])

    const _onEdited = (e: any) => {
        e.layers.eachLayer((layer: any) => {
            _syncLayerData(layer)
        })
    }

    const _onCreated = (e: any) => {
        _syncLayerData(e.layer)
    }

    const _onDeleted = (e: any) => {
        // Clear logic would go here, maybe setting state back to null
    }

    const _syncLayerData = (layer: any) => {
        if (layer instanceof L.Circle) {
            const center = layer.getLatLng()
            const radius = layer.getRadius()
            onChange({
                type: 'circle',
                coordinates: { lat: center.lat, lng: center.lng },
                radius: radius
            })
        } else if (layer instanceof L.Polygon) {
            const geojson = layer.toGeoJSON()
            onChange({
                type: 'polygon',
                coordinates: geojson.geometry
            })
        }
    }

    if (!mapReady) return <div style={{ height }} className="w-full bg-slate-100 animate-pulse rounded-md" />

    return (
        <div style={{ height }} className="w-full rounded-md border border-slate-200 overflow-hidden relative z-0">
            <MapContainer
                center={DefaultPosition}
                zoom={11}
                style={{ height: '100%', width: '100%' }}
            >
                <TileLayer
                    url="https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png"
                    attribution='&copy; <a href="https://carto.com/">Carto</a>'
                />
                <FeatureGroup>
                    <EditControl
                        position="topright"
                        onEdited={_onEdited}
                        onCreated={_onCreated}
                        onDeleted={_onDeleted}
                        draw={{
                            rectangle: false,
                            polyline: false,
                            circlemarker: false,
                            marker: false,
                            polygon: {
                                allowIntersection: false,
                                shapeOptions: {
                                    color: '#2563eb'
                                }
                            },
                            circle: {
                                shapeOptions: {
                                    color: '#2563eb'
                                }
                            }
                        }}
                    />
                </FeatureGroup>
            </MapContainer>
        </div>
    )
}

'use client'

import { useEffect, useRef } from 'react'
import * as L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import { Geofence } from '@/types'

delete (L.Icon.Default.prototype as any)._getIconUrl
L.Icon.Default.mergeOptions({
    iconRetinaUrl: '/leaflet/marker-icon-2x.png',
    iconUrl: '/leaflet/marker-icon.png',
    shadowUrl: '/leaflet/marker-shadow.png',
})

const COLORS = ['#2563eb', '#7c3aed', '#059669', '#d97706', '#dc2626', '#0891b2']

interface Props {
    geofences: Geofence[]
}

export default function GeofenceOverviewMap({ geofences }: Props) {
    const containerRef = useRef<HTMLDivElement>(null)
    const mapRef = useRef<L.Map | null>(null)

    useEffect(() => {
        if (!containerRef.current || mapRef.current) return

        const map = L.map(containerRef.current, {
            zoomControl: true,
            attributionControl: false,
            scrollWheelZoom: true,
        })

        L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png').addTo(map)
        mapRef.current = map

        const bounds: L.LatLngBounds[] = []

        geofences.forEach((g, idx) => {
            const color = COLORS[idx % COLORS.length]
            const { type, coordinates, radius, name } = g.attributes

            if (type === 'circle' && coordinates) {
                const lat = coordinates.lat ?? coordinates[1]
                const lng = coordinates.lng ?? coordinates[0]
                if (lat != null && lng != null) {
                    const circle = L.circle([lat, lng], {
                        radius: radius ?? 500,
                        color,
                        fillColor: color,
                        fillOpacity: 0.12,
                        weight: 2,
                    }).addTo(map)
                    circle.bindTooltip(`<strong>${name}</strong><br/>Circle ┬╖ ${radius ? `${(radius / 1000).toFixed(1)}km` : ''}`, {
                        className: 'leaflet-geofence-tooltip',
                    })
                    bounds.push(circle.getBounds())
                }
            } else if (type === 'polygon' && coordinates) {
                let latlngs: L.LatLngExpression[]
                if (coordinates.type === 'Polygon' && Array.isArray(coordinates.coordinates)) {
                    latlngs = coordinates.coordinates[0].map(([lng, lat]: [number, number]) => [lat, lng])
                } else if (Array.isArray(coordinates)) {
                    latlngs = coordinates.map((pt: any) =>
                        Array.isArray(pt) ? [pt[1], pt[0]] : [pt.lat, pt.lng]
                    )
                } else {
                    latlngs = []
                }
                if (latlngs.length > 0) {
                    const polygon = L.polygon(latlngs as L.LatLngExpression[], {
                        color,
                        fillColor: color,
                        fillOpacity: 0.12,
                        weight: 2,
                    }).addTo(map)
                    polygon.bindTooltip(`<strong>${name}</strong><br/>Polygon`, {
                        className: 'leaflet-geofence-tooltip',
                    })
                    bounds.push(polygon.getBounds())
                }
            }
        })

        if (bounds.length > 0) {
            const combined = bounds.reduce((acc, b) => acc.extend(b))
            map.fitBounds(combined, { padding: [40, 40] })
        } else {
            // Default to Lagos if no geofences have location data
            map.setView([6.5244, 3.3792], 10)
        }

        return () => {
            map.remove()
            mapRef.current = null
        }
    }, [geofences])

    return (
        <div
            ref={containerRef}
            className="h-full w-full"
        />
    )
}

'use client'

import React, { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Input } from '@/components/ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select'
import { Loader2, ShieldAlert, CheckCircle2, ArrowRight } from 'lucide-react'
import { IncidentStatus } from '@/types'
import { toast } from 'sonner'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import {
    startInvestigation,
    requireAction,
    logActionTaken,
    submitForResolution,
    resolveIncident,
    closeIncident,
    cancelIncident,
    dismissIncident,
    escalateIncident,
} from '@/lib/api/incidents'

interface ActionConfig {
    label: string
    variant: 'default' | 'destructive' | 'outline' | 'secondary'
    /** Which input fields are required/visible for this action */
    needsAssignee?: boolean
    needsSeverity?: boolean
    /** Human-readable label for the note textarea when shown */
    noteLabel?: string
    execute: (id: string, inputs: ActionInputs) => Promise<any>
}

interface ActionInputs {
    note: string
    assignedTo: string
    severity: string
}

const MACHINE_STATES: Partial<Record<IncidentStatus, ActionConfig[]>> = {
    reported: [
        {
            label: 'Start Investigation',
            variant: 'default',
            needsAssignee: true,
            execute: (id, { assignedTo }) => startInvestigation(id, assignedTo || id),
        },
        {
            label: 'Dismiss Incident',
            variant: 'destructive',
            noteLabel: 'Reason for dismissal (required)',
            execute: (id, { note }) => dismissIncident(id, note),
        },
    ],
    under_investigation: [
        {
            label: 'Action Required',
            variant: 'secondary',
            execute: (id) => requireAction(id),
        },
        {
            label: 'Escalate to Management',
            variant: 'destructive',
            needsSeverity: true,
            noteLabel: 'Escalation reason (required)',
            execute: (id, { note, severity }) => escalateIncident(id, note, severity || 'high'),
        },
        {
            label: 'Cancel Report',
            variant: 'outline',
            noteLabel: 'Reason for cancellation (required)',
            execute: (id, { note }) => cancelIncident(id, note),
        },
    ],
    action_required: [
        {
            label: 'Log Action Taken',
            variant: 'default',
            noteLabel: 'Describe the action taken (required)',
            execute: (id, { note }) => logActionTaken(id, note),
        },
        {
            label: 'Escalate',
            variant: 'destructive',
            needsSeverity: true,
            noteLabel: 'Escalation reason (required)',
            execute: (id, { note, severity }) => escalateIncident(id, note, severity || 'high'),
        },
    ],
    action_taken: [
        {
            label: 'Mark Pending Resolution',
            variant: 'default',
            noteLabel: 'Resolution notes',
            execute: (id, { note }) => submitForResolution(id, note),
        },
    ],
    pending_resolution: [
        {
            label: 'Resolve Incident',
            variant: 'default',
            noteLabel: 'Resolution notes (required)',
            execute: (id, { note }) => resolveIncident(id, note),
        },
        {
            label: 'More Action Required',
            variant: 'outline',
            execute: (id) => requireAction(id),
        },
    ],
    resolved: [
        {
            label: 'Close Record',
            variant: 'secondary',
            noteLabel: 'Closing notes (optional)',
            execute: (id, { note }) => closeIncident(id, note || undefined),
        },
    ],
    escalated: [
        {
            label: 'Resume Investigation',
            variant: 'default',
            needsAssignee: true,
            execute: (id, { assignedTo }) => startInvestigation(id, assignedTo || id),
        },
        {
            label: 'Close as Unresolved',
            variant: 'destructive',
            noteLabel: 'Closing notes (optional)',
            execute: (id, { note }) => closeIncident(id, note || undefined),
        },
    ],
    closed: [],
    cancelled: [],
    dismissed: [],
}

export function IncidentWorkflowActions({ id, currentStatus }: { id: string; currentStatus: IncidentStatus }) {
    const queryClient = useQueryClient()
    const [note, setNote] = useState('')
    const [assignedTo, setAssignedTo] = useState('')
    const [severity, setSeverity] = useState('high')
    const [activeAction, setActiveAction] = useState<ActionConfig | null>(null)

    const availableActions = MACHINE_STATES[currentStatus] ?? []
    const isTerminal = ['closed', 'cancelled', 'dismissed'].includes(currentStatus)

    const { mutate: executeAction, isPending } = useMutation({
        mutationFn: async (action: ActionConfig) => {
            return action.execute(id, { note, assignedTo, severity })
        },
        onSuccess: () => {
            toast.success('Incident status updated')
            setNote('')
            setAssignedTo('')
            setActiveAction(null)
            queryClient.invalidateQueries({ queryKey: ['incident', id] })
        },
        onError: (err: any) => {
            toast.error(err.response?.data?.message || 'Failed to update incident state')
        },
    })

    if (isTerminal) {
        return (
            <Card className="border-slate-200 shadow-sm opacity-75 bg-slate-50">
                <CardHeader className="border-b border-slate-100 flex flex-row items-center gap-3">
                    <CheckCircle2 className="h-5 w-5 text-slate-400" />
                    <div>
                        <CardTitle className="text-base text-slate-600">Workflow Completed</CardTitle>
                        <CardDescription>
                            This incident has reached a terminal state ({currentStatus.replace(/_/g, ' ')}) and cannot be transitioned further.
                        </CardDescription>
                    </div>
                </CardHeader>
            </Card>
        )
    }

    return (
        <Card className="border-slate-200 shadow-sm border-l-4 border-l-blue-600">
            <CardHeader className="bg-slate-50/50 border-b border-slate-100">
                <CardTitle className="text-base flex items-center gap-2">
                    <ShieldAlert className="h-4 w-4 text-blue-600" /> Resolution Workflow
                </CardTitle>
                <CardDescription>Advance this incident to the next state by selecting an action below.</CardDescription>
            </CardHeader>

            <CardContent className="p-6 space-y-4">
                <div className="bg-blue-50/50 p-3 rounded-md border border-blue-100">
                    <p className="text-sm font-medium text-blue-900 flex items-center gap-2">
                        Current Status <ArrowRight className="h-4 w-4 text-blue-400" />
                        <span className="uppercase tracking-wider px-2 py-0.5 bg-blue-100 rounded text-blue-800">
                            {currentStatus.replace(/_/g, ' ')}
                        </span>
                    </p>
                </div>

                {/* Contextual inputs ΓÇö only shown when an action requiring them is selected */}
                {activeAction?.needsAssignee && (
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700">Assign Investigator</label>
                        <Input
                            placeholder="Enter user ID or name..."
                            value={assignedTo}
                            onChange={(e) => setAssignedTo(e.target.value)}
                            className="bg-white"
                        />
                    </div>
                )}

                {activeAction?.needsSeverity && (
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700">Severity</label>
                        <Select value={severity} onValueChange={setSeverity}>
                            <SelectTrigger className="bg-white">
                                <SelectValue />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="low">Low</SelectItem>
                                <SelectItem value="medium">Medium</SelectItem>
                                <SelectItem value="high">High</SelectItem>
                                <SelectItem value="critical">Critical</SelectItem>
                            </SelectContent>
                        </Select>
                    </div>
                )}

                {activeAction?.noteLabel && (
                    <div className="space-y-1.5">
                        <label className="text-sm font-medium text-slate-700">
                            {activeAction.noteLabel}
                        </label>
                        <Textarea
                            placeholder="Add notes..."
                            value={note}
                            onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) => setNote(e.target.value)}
                            className="bg-white min-h-[90px]"
                        />
                    </div>
                )}

                {!activeAction && (
                    <p className="text-sm text-slate-500">Select an action below to proceed.</p>
                )}
            </CardContent>

            <CardFooter className="bg-slate-50 border-t border-slate-100 p-4 flex flex-wrap gap-3 justify-end rounded-b-lg">
                {activeAction ? (
                    <>
                        <Button variant="ghost" onClick={() => setActiveAction(null)} disabled={isPending}>
                            Cancel
                        </Button>
                        <Button
                            variant={activeAction.variant}
                            onClick={() => executeAction(activeAction)}
                            disabled={isPending}
                        >
                            {isPending && <Loader2 className="h-4 w-4 animate-spin mr-2" />}
                            Confirm: {activeAction.label}
                        </Button>
                    </>
                ) : (
                    availableActions.map((action, idx) => (
                        <Button
                            key={idx}
                            variant={action.variant}
                            onClick={() => {
                                // Actions with no extra inputs can fire immediately
                                if (!action.needsAssignee && !action.needsSeverity && !action.noteLabel) {
                                    executeAction(action)
                                } else {
                                    setNote('')
                                    setActiveAction(action)
                                }
                            }}
                            disabled={isPending}
                        >
                            {isPending ? <Loader2 className="h-4 w-4 animate-spin mr-2" /> : null}
                            {action.label}
                        </Button>
                    ))
                )}
            </CardFooter>
        </Card>
    )
}

