                                                            "flex h-5 items-center justify-center rounded-full text-[10px] font-black px-1.5",
                                                            isActive ? "bg-white text-blue-600" : "bg-rose-500 text-white shadow-sm shadow-rose-200",
                                                            isSidebarCollapsed && "absolute top-1 right-1 h-2 w-2 p-0 border border-white"
                                                        )}>
                                                            {!isSidebarCollapsed && unreadCount}
                                                        </div>
                                                    )}
                                                    {isLocked && (
                                                        <div className={cn(
                                                            "transition-all",
                                                            isSidebarCollapsed ? "absolute -top-1 -right-1 bg-white rounded-full p-0.5" : "bg-amber-100/50 p-1 rounded-md"
                                                        )}>
                                                            <Lock className={cn("text-amber-600", isSidebarCollapsed ? "h-2 w-2" : "h-3 w-3")} />
                                                        </div>
                                                    )}
                                                </div>
                                            </Link>
                                        )

                                        if (isSidebarCollapsed) {
                                            return (
                                                <Tooltip key={href}>
                                                    <TooltipTrigger asChild>
                                                        {itemContent}
                                                    </TooltipTrigger>
                                                    <TooltipContent side="right" sideOffset={15} className="bg-slate-900 border-none text-white px-3 py-1.5 font-bold text-xs ring-4 ring-slate-900/10">
                                                        {label} {isLocked ? '(UPGRADE TO UNLOCK)' : ''}
                                                    </TooltipContent>
                                                </Tooltip>
                                            )
                                        }

                                        return <React.Fragment key={href}>{itemContent}</React.Fragment>
                                    })}
                                </div>
                            </div>
                        )
                    })}
                </nav>

                <div className="p-4 border-t border-slate-50">
                    <div className={cn(
                        "flex items-center gap-3 p-2 rounded-xl border border-transparent transition-all",
                        !isSidebarCollapsed && "hover:bg-slate-50"
                    )}>
                        <div className="h-9 w-9 rounded-full bg-slate-100 shrink-0 overflow-hidden border-2 border-white shadow-sm">
                            <img src="/api/placeholder/100/100" alt="User" />
                        </div>
                        {!isSidebarCollapsed && (
                            <div className="min-w-0">
                                <p className="text-xs font-black text-slate-900 truncate">Suleiman Musa</p>
                                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-tighter">Fleet Admin</p>
                            </div>
                        )}
                    </div>
                </div>
            </aside>
        </TooltipProvider>
    )
}

'use client'

import { useEffect, useState } from 'react'
import { MapContainer, TileLayer, Marker, Popup, useMap, Polygon, Circle, Polyline } from 'react-leaflet'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import { cn } from '@/lib/utils'
import { Geofence } from '@/types'

// Robust icon creation using standard HTML string to avoid react-dom/server issues in some environments
const createVehicleIcon = (status: string, heading: number = 0, isSelected: boolean = false, isUpdating: boolean = false, isPlayback: boolean = false) => {
    let color = '#94a3b8' // Grey (active/offline/default)

    if (isPlayback) color = '#2563eb' // Blue for playback
    else if (status === 'in_transit') color = '#10b981' // Green
    else if (status === 'stopped') color = '#f59e0b' // Amber
    else if (status === 'offline') color = '#ef4444' // Red

    if (isSelected && !isPlayback) color = '#3b82f6'

    const html = `
        <div class="relative flex items-center justify-center w-[32px] h-[32px]">
            ${isUpdating ? '<div class="absolute inset-0 rounded-full bg-current opacity-20 animate-ping" style="color: ${color}"></div>' : ''}
            <div style="
                transform: rotate(${heading}deg);
                display: flex;
                align-items: center;
                justify-content: center;
                width: 32px;
                height: 32px;
                background: white;
                border-radius: 50%;
                border: 2px solid ${color};
                box-shadow: 0 4px 10px rgba(0,0,0,0.15);
                transition: transform 0.3s ease;
                z-index: 10;
            " class="${isSelected ? 'scale-110' : ''}">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="${color}" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round">
                    <polygon points="3 11 22 2 13 21 11 13 3 11"></polygon>
                </svg>
            </div>
        </div>
    `

    return L.divIcon({
        html,
        className: 'custom-vehicle-marker',
        iconSize: [32, 32],
        iconAnchor: [16, 16],
        popupAnchor: [0, -16]
    })
}

function MapController({ locations, selectedVehicleId }: { locations: { id: string; lat: number; lng: number }[]; selectedVehicleId: string | null }) {
    const map = useMap()
    const [hasFitted, setHasFitted] = useState(false)

    // Handle initial bounds fitting
    useEffect(() => {
        if (!hasFitted && locations.length > 0) {
            const validLocations = locations.filter(loc => loc.lat !== 0 && loc.lng !== 0)
            if (validLocations.length > 0) {
                const bounds = L.latLngBounds(validLocations.map(loc => [loc.lat, loc.lng]))
                map.fitBounds(bounds, { padding: [50, 50], maxZoom: 15 })
                setHasFitted(true)
            }
        }
    }, [locations, map, hasFitted])

    // Handle smooth fly-to on selection
    useEffect(() => {
        if (selectedVehicleId) {
            const selected = locations.find(v => v.id === selectedVehicleId)
            if (selected && selected.lat !== 0 && selected.lng !== 0) {
                map.flyTo([selected.lat, selected.lng], 17, { duration: 1.5 })
            }
        }
    }, [selectedVehicleId, map, locations])

    return null
}

interface LiveMapProps {
    vehicles: {
        id: string
        registration_number: string
        latitude: number
        longitude: number
        speed: number
        heading: number
        status: string
        last_update?: string
    }[]
    geofences?: Geofence[]
    activeTripRoute?: any[]
    playbackMarker?: {
        latitude: number
        longitude: number
        heading: number
        speed: number
    }
    selectedVehicleId: string | null
    onSelectVehicle: (id: string) => void
}

export default function LiveMapComponent({
    vehicles,
    geofences = [],
    activeTripRoute = [],
    playbackMarker,
    selectedVehicleId,
    onSelectVehicle
}: LiveMapProps) {
    const [mounted, setMounted] = useState(false)
    const [updatingVehicles, setUpdatingVehicles] = useState<Record<string, boolean>>({})

    useEffect(() => {
        setMounted(true)
    }, [])

    // Trigger ping effect when last_update changes
    useEffect(() => {
        vehicles.forEach(v => {
            if (v.last_update) {
                setUpdatingVehicles(prev => ({ ...prev, [v.id]: true }))
                setTimeout(() => {
                    setUpdatingVehicles(prev => {
                        const next = { ...prev }
                        delete next[v.id]
                        return next
                    })
                }, 1000)
            }
        })
    }, [vehicles.map(v => v.last_update).join(',')])

    if (!mounted) return (
        <div className="w-full h-full bg-slate-100 flex items-center justify-center">
            <span className="text-xs font-black text-slate-400 uppercase tracking-widest animate-pulse">Initializing Tracking Engine...</span>
        </div>
    )

    const initialCenter: [number, number] = vehicles.length > 0 && vehicles[0].latitude !== 0
        ? [vehicles[0].latitude, vehicles[0].longitude]
        : [6.5244, 3.3792]

    return (
        <div className="w-full h-full relative z-0" style={{ height: '100%', minHeight: '400px' }}>
            <MapContainer
                center={initialCenter}
                zoom={12}
                scrollWheelZoom={true}
                className="w-full h-full"
                zoomControl={false}
            >
                <TileLayer
                    attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
                    url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
                />

                {geofences.map((gf) => {
                    const { type, coordinates, radius, name } = gf.attributes
                    const pathOptions = {
                        color: '#4f7cff',
                        fillColor: '#4f7cff',
                        fillOpacity: 0.08,
                        weight: 2
                    }

                    if (type === 'polygon' && Array.isArray(coordinates)) {
                        return (
                            <Polygon
                                key={gf.id}
                                positions={coordinates as any}
                                pathOptions={pathOptions}
                            >
                                <Popup>{name}</Popup>
                            </Polygon>
                        )
                    }
                    if (type === 'circle' && radius && Array.isArray(coordinates)) {
                        return (
                            <Circle
                                key={gf.id}
                                center={coordinates as [number, number]}
                                radius={radius}
                                pathOptions={pathOptions}
                            >
                                <Popup>{name}</Popup>
                            </Circle>
                        )
                    }
                    return null
                })}

                {activeTripRoute.length > 0 && (
                    <>
                        <Polyline
                            positions={activeTripRoute.map(r => [r.coordinates.latitude, r.coordinates.longitude])}
                            pathOptions={{ color: '#2563eb', weight: 4 }}
                        />
                        {activeTripRoute.filter(r => r.is_checkpoint).map((cp, idx) => (
                            <Circle
                                key={`cp-${idx}`}
                                center={[cp.coordinates.latitude, cp.coordinates.longitude]}
                                radius={50}
                                pathOptions={{ color: '#10b981', fillColor: '#10b981', fillOpacity: 0.5 }}
                            >
                                <Popup>Checkpoint: {cp.location_name}</Popup>
                            </Circle>
                        ))}
                    </>
                )}

                {playbackMarker && (
                    <Marker
                        position={[playbackMarker.latitude, playbackMarker.longitude]}
                        icon={createVehicleIcon('in_transit', playbackMarker.heading, true, false, true)}
                        zIndexOffset={1000}
                    />
                )}

                <MapController
                    locations={vehicles.map(v => ({ id: v.id, lat: v.latitude, lng: v.longitude }))}
                    selectedVehicleId={selectedVehicleId}
                />

                {vehicles.map((v) => {
                    // Skip rendering markers at (0,0) or missing coords
                    if (!v.latitude || !v.longitude || (Math.abs(v.latitude) < 0.0001 && Math.abs(v.longitude) < 0.0001)) {
                        return null;
                    }

                    return (
                        <Marker
                            key={v.id}
                            position={[v.latitude, v.longitude]}
                            icon={createVehicleIcon(v.status, v.heading, selectedVehicleId === v.id, updatingVehicles[v.id])}
                            eventHandlers={{
                                click: () => onSelectVehicle(v.id)
                            }}
                        >
                            <Popup className="custom-map-popup">
                                <div className="p-2 min-w-[150px]">
                                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Vehicle Asset</p>
                                    <p className="text-sm font-black text-slate-900 italic mb-1">{v.registration_number}</p>
                                    <div className="flex items-center justify-between mt-2">
                                        <span className="text-[10px] font-bold text-blue-600 font-mono tracking-tighter">{v.speed} KPH</span>
                                        <span className={cn(
                                            "h-2 w-2 rounded-full",
                                            v.status === 'online' ? "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]" : "bg-rose-500 shadow-[0_0_8px_rgba(244,63,94,0.5)]"
                                        )} />
                                    </div>
                                </div>
                            </Popup>
                        </Marker>
                    )
                })}
            </MapContainer>

            <style jsx global>{`
                .custom-vehicle-marker {
                    background: transparent !important;
                    border: none !important;
                }
                .custom-map-popup .leaflet-popup-content-wrapper {
                    border-radius: 12px;
                    border: 1px solid #f1f5f9;
                    box-shadow: 0 10px 25px -5px rgba(0,0,0,0.1);
                    padding: 4px;
                }
                .custom-map-popup .leaflet-popup-tip-container {
                    display: none;
                }
            `}</style>
        </div>
    )
}

'use client'

import React from 'react'
import { MaintenanceJob, MaintenanceJobStatus } from '@/types'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { format } from 'date-fns'
import Link from 'next/link'
import { Wrench, Calendar, Clock, AlertTriangle } from 'lucide-react'
import { useMutation, useQueryClient } from '@tanstack/react-query'
import { transitionMaintenanceJob } from '@/lib/api/maintenance'
import { toast } from 'sonner'
import { Button } from '@/components/ui/button'

const COLUMNS: { id: MaintenanceJobStatus; label: string; color: string }[] = [
    { id: 'draft', label: 'Draft', color: 'bg-slate-100 text-slate-700' },
    { id: 'submitted', label: 'Submitted', color: 'bg-amber-100 text-amber-800' },
    { id: 'approved', label: 'Approved', color: 'bg-blue-100 text-blue-800' },
    { id: 'in_progress', label: 'In Progress', color: 'bg-violet-100 text-violet-800' },
    { id: 'pending_verification', label: 'Pending Verification', color: 'bg-orange-100 text-orange-800' },
    { id: 'verified', label: 'Verified', color: 'bg-emerald-100 text-emerald-800' },
    { id: 'closed', label: 'Closed', color: 'bg-slate-200 text-slate-800' },
    { id: 'rejected', label: 'Rejected', color: 'bg-rose-100 text-rose-800' },
]

interface MaintenanceKanbanProps {
    jobs: MaintenanceJob[]
    isLoading?: boolean
}

export function MaintenanceKanban({ jobs, isLoading }: MaintenanceKanbanProps) {
    const queryClient = useQueryClient()

    // Simple transition logic for MVP without full drag-and-drop
    // In a real kanban, we'd use @dnd-kit or react-beautiful-dnd
    const { mutate: updateStatus, isPending } = useMutation({
        mutationFn: ({ id, status }: { id: string, status: string }) => transitionMaintenanceJob(id, { to_status: status }),
        onSuccess: () => {
            toast.success('Job status updated')
            queryClient.invalidateQueries({ queryKey: ['maintenance-jobs'] })
        },
        onError: () => toast.error('Failed to update status')
    })

    if (isLoading) {
        return <div className="p-8 text-center text-slate-500">Loading job board...</div>
    }

    const jobsByStatus = COLUMNS.reduce((acc, col) => {
        acc[col.id] = jobs?.filter(job => job.attributes.status === col.id) || []
        return acc
    }, {} as Record<MaintenanceJobStatus, MaintenanceJob[]>)

    const getPriorityColor = (priority: string) => {
        switch (priority) {
            case 'urgent': return 'text-rose-600 bg-rose-50 border-rose-200'
            case 'high': return 'text-amber-600 bg-amber-50 border-amber-200'
            case 'medium': return 'text-blue-600 bg-blue-50 border-blue-200'
            default: return 'text-slate-600 bg-slate-50 border-slate-200'
        }
    }

    return (
        <div className="flex gap-4 overflow-x-auto pb-4 h-[calc(100vh-12rem)]">
            {COLUMNS.map((column) => (
                <div key={column.id} className="flex-shrink-0 w-80 bg-slate-100/50 rounded-xl border border-slate-200 flex flex-col h-full overflow-hidden">
                    <div className="p-3 border-b border-slate-200 bg-white/50 flex items-center justify-between sticky top-0">
                        <div className="flex items-center gap-2">
                            <span className={`w-2 h-2 rounded-full ${column.color.split(' ')[0]}`} />
                            <h3 className="font-semibold text-slate-900 text-sm">{column.label}</h3>
                        </div>
                        <Badge variant="secondary" className="bg-slate-200 text-slate-700">
                            {jobsByStatus[column.id].length}
                        </Badge>
                    </div>

                    <div className="flex-1 overflow-y-auto p-3 space-y-3 custom-scrollbar">
                        {jobsByStatus[column.id].map(job => (
                            <Card key={job.id} className="shadow-sm hover:shadow-md transition-shadow cursor-pointer group border-slate-200">
                                <Link href={`/maintenance/jobs/${job.id}`}>
                                    <div className="p-4 flex flex-col gap-3">
                                        <div className="flex items-start justify-between gap-2">
                                            <Badge variant="outline" className="text-[10px] font-mono uppercase bg-slate-50">
                                                {job.attributes.reference_number}
                                            </Badge>
                                            <Badge variant="outline" className={`text-[10px] capitalize ${getPriorityColor(job.attributes.priority)}`}>
                                                {job.attributes.priority}
                                            </Badge>
                                        </div>

                                        <div>
                                            <h4 className="text-sm font-semibold text-slate-900 leading-tight group-hover:text-blue-600 transition-colors">
                                                {job.attributes.description}
                                            </h4>
                                            {job.relationships?.vehicle && (
                                                <div className="flex items-center gap-1.5 mt-2 text-xs text-slate-500">
                                                    <Wrench className="h-3 w-3" />
                                                    <span>{'registration_number' in job.relationships.vehicle ? job.relationships.vehicle.registration_number : (job.relationships.vehicle as any).data?.id}</span>
                                                </div>
                                            )}
                                        </div>

                                        <div className="flex items-center justify-between pt-3 border-t border-slate-100">
                                            <div className="flex items-center gap-1.5 text-xs text-slate-500">
                                                <Calendar className="h-3.5 w-3.5" />
                                                <span>{job.attributes.scheduled_date ? format(new Date(job.attributes.scheduled_date), 'MMM dd') : 'TBD'}</span>
                                            </div>

                                            {job.relationships.assignee?.data ? (
                                                <div className="flex -space-x-1">
                                                    <div className="w-6 h-6 rounded-full bg-blue-100 border border-white flex items-center justify-center text-[10px] font-bold text-blue-700">
                                                        {job.relationships.assignee.data.id.substring(0, 2).toUpperCase()}
                                                    </div>
                                                </div>
                                            ) : (
                                                <span className="text-[10px] text-slate-400 italic">Unassigned</span>
                                            )}
                                        </div>
                                    </div>
                                </Link>

                                {/* Quick Actions (MVP - usually would be DND) */}
                                <div className="px-4 pb-3 pt-0 flex gap-2">
                                    <Button
                                        variant="outline"
                                        size="sm"
                                        className="h-7 text-xs w-full"
                                        disabled={isPending}
                                        onClick={(e) => {
                                            e.preventDefault()
                                            // Simplistic next-status logic
                                            const currIdx = COLUMNS.findIndex(c => c.id === job.attributes.status)
                                            if (currIdx < COLUMNS.length - 1) {
                                                updateStatus({ id: job.id, status: COLUMNS[currIdx + 1].id })
                                            }
                                        }}
                                    >
                                        Advance Status
                                    </Button>
                                </div>
                            </Card>
                        ))}
                        {jobsByStatus[column.id].length === 0 && (
                            <div className="h-24 flex items-center justify-center border-2 border-dashed border-slate-200 rounded-lg bg-slate-50/50">
                                <span className="text-xs text-slate-400">No jobs</span>
                            </div>
                        )}
                    </div>
                </div>
            ))}
        </div>
    )
}

'use client'

import React, { useEffect, useState } from 'react'
import { useAuthStore } from '@/store/authStore'
import { Card, CardContent } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ShieldAlert, ArrowLeft, Loader2 } from 'lucide-react'
import { useRouter } from 'next/navigation'

interface RoleGateProps {
    children: React.ReactNode
    allowedRoles: string[]
    fallbackMessage?: string
}

export function RoleGate({
    children,
    allowedRoles,
    fallbackMessage = "You do not have the required permissions to view this secure area."
}: RoleGateProps) {
    const { user } = useAuthStore()
    const router = useRouter()
    const [isMounted, setIsMounted] = useState(false)

    useEffect(() => {
        setIsMounted(true)
    }, [])

    if (!isMounted) {
        return (
            <div className="flex h-[400px] w-full items-center justify-center">
                <Loader2 className="h-8 w-8 animate-spin text-slate-300" />
            </div>
        )
    }

    if (!user) {
        // Handled by higher-up layout middleware ideally, but fallback here
        return null
    }

    const userRoles = Array.isArray(user.attributes.role) ? user.attributes.role : [user.attributes.role]
    const hasAccess = userRoles.some(r => allowedRoles.includes(r as string))

    if (!hasAccess) {
        return (
            <div className="flex h-[calc(100vh-64px)] w-full items-center justify-center bg-slate-50 p-6">
                <Card className="w-full max-w-md shadow-sm border-slate-200">
                    <CardContent className="flex flex-col items-center justify-center pt-10 pb-8 px-8 text-center">
                        <div className="h-16 w-16 bg-rose-100 rounded-full flex items-center justify-center mb-6 ring-8 ring-rose-50">
                            <ShieldAlert className="h-8 w-8 text-rose-600" />
                        </div>
                        <h2 className="text-xl font-bold text-slate-900 mb-2">Restricted Access</h2>
                        <p className="text-slate-500 mb-8">{fallbackMessage}</p>

                        <div className="w-full space-y-3">
                            <Button
                                className="w-full"
                                onClick={() => router.push('/dashboard')}
                            >
                                <ArrowLeft className="mr-2 h-4 w-4" /> Return to Dashboard
                            </Button>
                        </div>
                    </CardContent>
                </Card>
            </div>
        )
    }

    return <>{children}</>
}

import React from 'react'
