import { LocationAutocomplete } from '@/components/ui/LocationAutocomplete'
import { addMinutes, format } from 'date-fns'
import { cn } from '@/lib/utils'

interface EditTripModalProps {
    isOpen: boolean
    onClose: () => void
    trip: Trip | null
}

export function EditTripModal({ isOpen, onClose, trip }: EditTripModalProps) {
    const queryClient = useQueryClient()
    const [formData, setFormData] = React.useState({
        start_location: {
            name: '',
            coords: { latitude: 0, longitude: 0 }
        },
        end_location: {
            name: '',
            coords: { latitude: 0, longitude: 0 }
        },
        planned_start_time: '',
        planned_end_time: '',
    })
    const [isCalculatingEta, setIsCalculatingEta] = React.useState(false)
    const [etaMinutes, setEtaMinutes] = React.useState<number | null>(null)

    React.useEffect(() => {
        if (trip) {
            const startLoc = typeof trip.attributes.start_location === 'string'
                ? { name: trip.attributes.start_location, coords: { latitude: 6.5244, longitude: 3.3792 } }
                : trip.attributes.start_location || { name: '', coords: { latitude: 0, longitude: 0 } }

            const endLoc = typeof trip.attributes.end_location === 'string'
                ? { name: trip.attributes.end_location, coords: { latitude: 6.4281, longitude: 3.4276 } }
                : trip.attributes.end_location || { name: '', coords: { latitude: 0, longitude: 0 } }

            setFormData({
                start_location: startLoc,
                end_location: endLoc,
                planned_start_time: trip.attributes.planned_start_time ? new Date(trip.attributes.planned_start_time).toISOString().slice(0, 16) : '',
                planned_end_time: trip.attributes.planned_end_time ? new Date(trip.attributes.planned_end_time).toISOString().slice(0, 16) : '',
            })
        }
    }, [trip])

    const updateField = (field: string, value: any) => {
        setFormData(prev => {
            const newData = { ...prev, [field]: value }

            // Auto-update end time if start time or ETA changes
            if ((field === 'planned_start_time' || field === 'etaMinutes') && newData.planned_start_time && etaMinutes) {
                const startTime = new Date(newData.planned_start_time)
                const endTime = addMinutes(startTime, etaMinutes)
                newData.planned_end_time = format(endTime, "yyyy-MM-dd'T'HH:mm")
            }

            return newData
        })
    }

    const handleLocationSelect = async (type: 'start' | 'end', location: any) => {
        const newFormData = {
            ...formData,
            [type === 'start' ? 'start_location' : 'end_location']: location
        }
        setFormData(newFormData)

        if (newFormData.start_location.coords.latitude !== 0 && newFormData.end_location.coords.latitude !== 0) {
            setIsCalculatingEta(true)
            try {
                const response = await calculateTripEstimate({
                    start_location: newFormData.start_location,
                    end_location: newFormData.end_location
                })

                const parsedMinutes = 120 // Fallback/Mock
                setEtaMinutes(parsedMinutes)

                if (newFormData.planned_start_time) {
                    const startTime = new Date(newFormData.planned_start_time)
                    const endTime = addMinutes(startTime, parsedMinutes)
                    setFormData(prev => ({
                        ...prev,
                        [type === 'start' ? 'start_location' : 'end_location']: location,
                        planned_end_time: format(endTime, "yyyy-MM-dd'T'HH:mm")
                    }))
                }
                toast.success(`Estimated arrival: ${response.data.eta}`)
            } catch (error) {
                console.error('Failed to calculate ETA', error)
            } finally {
                setIsCalculatingEta(false)
            }
        }
    }

    const { mutate: handleUpdate, isPending } = useMutation({
        mutationFn: () => updateTrip(trip!.id, formData),
        onSuccess: () => {
            toast.success('Trip updated successfully')
            queryClient.invalidateQueries({ queryKey: ['trips'] })
            onClose()
        },
        onError: (error: any) => {
            toast.error(error.response?.data?.message || 'Failed to update trip')
        }
    })

    if (!trip) return null

    return (
        <Dialog open={isOpen} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-[500px]">
                <DialogHeader>
                    <DialogTitle>Edit Trip Details</DialogTitle>
                    <DialogDescription>
                        Update the route and schedule for trip <span className="font-bold text-slate-900">{trip.attributes.trip_number}</span>.
                    </DialogDescription>
                </DialogHeader>

                <div className="py-6 space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Origin</Label>
                            <LocationAutocomplete
                                value={formData.start_location.name}
                                onSelect={(loc) => handleLocationSelect('start', loc)}
                                placeholder="Search origin..."
                                icon={<Navigation className="h-4 w-4 text-blue-600" />}
                            />
                        </div>
                        <div className="space-y-2">
                            <Label>Destination</Label>
                            <LocationAutocomplete
                                value={formData.end_location.name}
                                onSelect={(loc) => handleLocationSelect('end', loc)}
                                placeholder="Search destination..."
                                icon={<MapPin className="h-4 w-4 text-emerald-600" />}
                            />
                        </div>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <div className="space-y-2">
                            <Label>Planned Start</Label>
                            <div className="relative">
                                <Calendar className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
                                <Input
                                    type="datetime-local"
                                    className="pl-10 h-11"
                                    value={formData.planned_start_time}
                                    onChange={(e) => setFormData(prev => ({ ...prev, planned_start_time: e.target.value }))}
                                />
                            </div>
                        </div>
                        <div className="space-y-2">
                            <Label>Planned End (ETA)</Label>
                            <div className="relative">
                                <Calendar className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
                                <Input
                                    type="datetime-local"
                                    className={cn("pl-10 h-11", isCalculatingEta && "opacity-50")}
                                    value={formData.planned_end_time}
                                    onChange={(e) => updateField('planned_end_time', e.target.value)}
                                />
                                {isCalculatingEta && (
                                    <div className="absolute right-3 top-3">
                                        <Loader2 className="h-4 w-4 animate-spin text-blue-600" />
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                <DialogFooter>
                    <Button variant="ghost" onClick={onClose} disabled={isPending}>
                        Cancel
                    </Button>
                    <Button
                        onClick={() => handleUpdate()}
                        disabled={isPending}
                        className="bg-blue-600 hover:bg-blue-700"
                    >
                        {isPending ? (
                            <>
                                <Loader2 className="mr-2 h-4 w-4 animate-spin" /> Saving...
                            </>
                        ) : (
                            'Save Changes'
                        )}
                    </Button>
                </DialogFooter>
            </DialogContent>
        </Dialog>
    )
}

'use client'

import React from 'react'
import {
    ColumnDef,
    flexRender,
    getCoreRowModel,
    useReactTable,
} from '@tanstack/react-table'

import {
    Table,
    TableBody,
    TableCell,
    TableHead,
    TableHeader,
    TableRow,
} from '@/components/ui/table'
import { Trip } from '@/types'
import { MoreHorizontal, Eye, Edit, MapPin, Route } from 'lucide-react'
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Button } from '@/components/ui/button'
import Link from 'next/link'
import { format } from 'date-fns'
import { TripStatusBadge } from './TripStatusBadge'

import {
    Pagination,
    PaginationContent,
    PaginationItem,
    PaginationLink,
    PaginationNext,
    PaginationPrevious,
} from '@/components/ui/pagination'

interface TripTableProps {
    data: Trip[]
    isLoading?: boolean
    pagination?: {
        current: number
        lastPage: number
        total: number
    }
    onPageChange?: (page: number) => void
    onEdit?: (trip: Trip) => void
    onChangeStatus?: (trip: Trip) => void
}

export function TripTable({
    data,
    isLoading,
    pagination,
    onPageChange,
    onEdit,
    onChangeStatus
}: TripTableProps) {
    const columns: ColumnDef<Trip>[] = React.useMemo(() => [
        {
            accessorKey: 'attributes.trip_number',
            header: 'Ref / ID',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="font-bold text-slate-900 group-hover:text-blue-600 transition-colors">
                        {row.original.attributes.trip_number}
                    </span>
                    <span className="text-[10px] text-slate-400 font-mono uppercase tracking-tighter">
                        ID: {row.original.id}
                    </span>
                </div>
            ),
        },
        {
            header: 'Route',
            cell: ({ row }) => {
                const startLoc = row.original.attributes.start_location
                const endLoc = row.original.attributes.end_location
                const startName = typeof startLoc === 'string' ? startLoc : startLoc?.name || 'Unknown'
                const endName = typeof endLoc === 'string' ? endLoc : endLoc?.name || 'Unknown'

                return (
                    <div className="flex flex-col gap-0.5 max-w-[200px]">
                        <div className="flex items-center gap-1.5 overflow-hidden">
                            <MapPin className="h-3 w-3 text-slate-400 shrink-0" />
                            <span className="text-xs font-medium text-slate-700 truncate">{startName}</span>
                        </div>
                        <div className="h-2 w-px bg-slate-200 ml-1.5" />
                        <div className="flex items-center gap-1.5 overflow-hidden">
                            <MapPin className="h-3 w-3 text-blue-500 shrink-0" />
                            <span className="text-xs font-medium text-slate-700 truncate">{endName}</span>
                        </div>
                    </div>
                )
            },
        },
        {
            header: 'Vehicle / Driver',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="text-sm font-medium text-slate-900 capitalize">
                        {row.original.attributes.vehicle_id ? `Vehicle: ${row.original.attributes.vehicle_id}` : 'No Vehicle'}
                    </span>
                    <span className="text-xs text-slate-500">
                        {row.original.attributes.driver_id ? `Driver: ${row.original.attributes.driver_id}` : 'No Driver'}
                    </span>
                </div>
            ),
        },
        {
            accessorKey: 'attributes.status',
            header: 'Status',
            cell: ({ row }) => <TripStatusBadge status={row.original.attributes.status} />,
        },
        {
            header: 'Schedule',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="text-xs font-medium text-slate-700">
                        {row.original.attributes.planned_start_time ? format(new Date(row.original.attributes.planned_start_time), 'MMM dd, HH:mm') : 'N/A'}
                    </span>
                    <span className="text-[10px] text-slate-400 italic">
                        Start Time
                    </span>
                </div>
            ),
        },
        {
            id: 'actions',
            cell: ({ row }) => {
                const trip = row.original

                return (
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className="h-8 w-8 p-0">
                                <span className="sr-only">Open menu</span>
                                <MoreHorizontal className="h-4 w-4" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                            <DropdownMenuLabel>Actions</DropdownMenuLabel>
                            <DropdownMenuItem asChild>
                                <Link href={`/trips/${trip.id}`}>
                                    <Eye className="mr-2 h-4 w-4" /> View Details
                                </Link>
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => onEdit?.(trip)}>
                                <Edit className="mr-2 h-4 w-4" /> Edit Trip
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => onChangeStatus?.(trip)}>
                                <Route className="mr-2 h-4 w-4" /> Change Status
                            </DropdownMenuItem>
                            <DropdownMenuSeparator />
                            <DropdownMenuItem className="text-rose-600 focus:text-rose-600">
                                Cancel Trip
                            </DropdownMenuItem>
                        </DropdownMenuContent>
                    </DropdownMenu>
                )
            },
        },
    ], [])

    const table = useReactTable({
        data,
        columns,
        getCoreRowModel: getCoreRowModel(),
    })

    if (isLoading) {
        return <div className="p-8 text-center text-slate-500">Loading trips...</div>
    }

    return (
        <div className="space-y-4">
            <div className="rounded-md border border-slate-200 bg-white shadow-sm overflow-hidden">
                <Table>
                    <TableHeader className="bg-slate-50">
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow key={headerGroup.id}>
                                {headerGroup.headers.map((header) => (
                                    <TableHead key={header.id}>
                                        {header.isPlaceholder
                                            ? null
                                            : flexRender(
                                                header.column.columnDef.header,
                                                header.getContext()
                                            )}
                                    </TableHead>
                                ))}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {table.getRowModel().rows?.length ? (
                            table.getRowModel().rows.map((row) => (
                                <TableRow
                                    key={row.id}
                                    className="hover:bg-slate-50/50 group"
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell key={cell.id}>
                                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        ) : (
                            <TableRow>
                                <TableCell colSpan={columns.length} className="h-24 text-center">
                                    No trips found.
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </div>

            {pagination && pagination.lastPage > 1 && (
                <div className="flex items-center justify-between px-2">
                    <p className="text-sm text-slate-500">
                        Showing <span className="font-medium text-slate-900">{data.length}</span> of <span className="font-medium text-slate-900">{pagination.total}</span> trips
                    </p>
                    <Pagination className="mx-0 w-auto">
                        <PaginationContent>
                            <PaginationItem>
                                <PaginationPrevious
                                    href="#"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        if (pagination.current > 1) onPageChange?.(pagination.current - 1);
                                    }}
                                    className={pagination.current === 1 ? "pointer-events-none opacity-50" : "cursor-pointer"}
                                />
                            </PaginationItem>

                            {Array.from({ length: Math.min(5, pagination.lastPage) }, (_, i) => {
                                let pageNum = i + 1;
                                if (pagination.lastPage > 5) {
                                    if (pagination.current > 3) {
                                        pageNum = pagination.current - 2 + i;
                                        if (pageNum > pagination.lastPage) pageNum = pagination.lastPage - 4 + i;
                                    }
                                }
                                if (pageNum <= 0) return null;
                                if (pageNum > pagination.lastPage) return null;

                                return (
                                    <PaginationItem key={pageNum}>
                                        <PaginationLink
                                            href="#"
                                            isActive={pagination.current === pageNum}
                                            onClick={(e) => {
                                                e.preventDefault();
                                                onPageChange?.(pageNum);
                                            }}
                                            className="cursor-pointer"
                                        >
                                            {pageNum}
                                        </PaginationLink>
                                    </PaginationItem>
                                )
                            })}

                            <PaginationItem>
                                <PaginationNext
                                    href="#"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        if (pagination.current < pagination.lastPage) onPageChange?.(pagination.current + 1);
                                    }}
                                    className={pagination.current === pagination.lastPage ? "pointer-events-none opacity-50" : "cursor-pointer"}
                                />
                            </PaginationItem>
                        </PaginationContent>
                    </Pagination>
                </div>
            )}
        </div>
    )
}

'use client'

import React, { useState, useEffect, useRef } from 'react'
import { Input } from '@/components/ui/input'
import { Search, MapPin, Loader2, X } from 'lucide-react'
import { cn } from '@/lib/utils'
import axios from 'axios'

interface Location {
    name: string
    coords: {
        latitude: number
        longitude: number
    }
}

interface LocationAutocompleteProps {
    value: string
    onSelect: (location: Location) => void
    placeholder?: string
    className?: string
    icon?: React.ReactNode
}

export function LocationAutocomplete({
    value,
    onSelect,
    placeholder = "Search location...",
    className,
    icon
}: LocationAutocompleteProps) {
    const [inputValue, setInputValue] = useState(value)
    const [suggestions, setSuggestions] = useState<any[]>([])
    const [isLoading, setIsLoading] = useState(false)
    const [isOpen, setIsOpen] = useState(false)
    const containerRef = useRef<HTMLDivElement>(null)
    const token = process.env.NEXT_PUBLIC_MAPBOX_TOKEN

    useEffect(() => {
        setInputValue(value)
    }, [value])

    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
                setIsOpen(false)
            }
        }
        document.addEventListener('mousedown', handleClickOutside)
        return () => document.removeEventListener('mousedown', handleClickOutside)
    }, [])

    const fetchSuggestions = async (query: string) => {
        if (!query || query.length < 3 || !token) {
            setSuggestions([])
            return
        }

        setIsLoading(true)
        try {
            const response = await axios.get(
                `https://api.mapbox.com/geocoding/v5/mapbox.places/${encodeURIComponent(query)}.json`,
                {
                    params: {
                        access_token: token,
                        autocomplete: true,
                        limit: 5,
                        country: 'NG', // Focusing on Nigeria as per project context
                        types: 'address,poi,place'
                    }
                }
            )
            setSuggestions(response.data.features || [])
            setIsOpen(true)
        } catch (error) {
            console.error('Error fetching Mapbox suggestions:', error)
        } finally {
            setIsLoading(false)
        }
    }

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value
        setInputValue(val)

        // Debounce
        const timeoutId = setTimeout(() => {
            fetchSuggestions(val)
        }, 500)
        return () => clearTimeout(timeoutId)
    }

    const handleSelect = (feature: any) => {
        const location: Location = {
            name: feature.place_name,
            coords: {
                longitude: feature.center[0],
                latitude: feature.center[1]
            }
        }
        setInputValue(feature.place_name)
        setSuggestions([])
        setIsOpen(false)
        onSelect(location)
    }

    const clearInput = () => {
        setInputValue('')
        setSuggestions([])
        setIsOpen(false)
    }

    return (
        <div className={cn("relative w-full", className)} ref={containerRef}>
            <div className="relative">
                {icon ? (
                    <div className="absolute left-3 top-1/2 -translate-y-1/2">
                        {icon}
                    </div>
                ) : (
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400" />
                )}

                <Input
                    className={cn(
                        "h-12 w-full",
                        icon || true ? "pl-10" : "pl-4",
                        "pr-10"
                    )}
                    placeholder={placeholder}
                    value={inputValue}
                    onChange={handleInputChange}
                    onFocus={() => suggestions.length > 0 && setIsOpen(true)}
                />

                <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center gap-2">
                    {isLoading && <Loader2 className="h-4 w-4 animate-spin text-slate-400" />}
                    {inputValue && (
                        <button
                            onClick={clearInput}
                            className="text-slate-400 hover:text-slate-600 transition-colors"
                        >
                            <X className="h-4 w-4" />
                        </button>
                    )}
                </div>
            </div>

            {isOpen && suggestions.length > 0 && (
                <div className="absolute z-50 w-full mt-1 bg-white border border-slate-200 rounded-xl shadow-xl overflow-hidden animate-in fade-in zoom-in-95 duration-200">
                    <div className="max-h-[300px] overflow-y-auto overflow-x-hidden p-1">
                        {suggestions.map((feature) => (
                            <button
                                key={feature.id}
                                onClick={() => handleSelect(feature)}
                                className="w-full flex items-start gap-3 p-3 hover:bg-slate-50 transition-colors rounded-lg text-left group"
                            >
                                <div className="mt-1 h-7 w-7 rounded-lg bg-slate-50 flex items-center justify-center group-hover:bg-blue-50 transition-colors">
                                    <MapPin className="h-4 w-4 text-slate-400 group-hover:text-blue-600 transition-colors" />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <p className="text-sm font-bold text-slate-900 truncate">
                                        {feature.text}
                                    </p>
                                    <p className="text-[11px] text-slate-500 line-clamp-2 mt-0.5 leading-relaxed">
                                        {feature.place_name}
                                    </p>
                                </div>
                            </button>
                        ))}
                    </div>
                    <div className="p-2 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
                        <span className="text-[9px] font-black uppercase tracking-widest text-slate-400">Powered by Mapbox</span>
                    </div>
                </div>
            )}
        </div>
    )
}

