interface VehicleTableProps {
    data: Vehicle[]
    isLoading?: boolean
    onAssign?: (vehicle: Vehicle) => void
    onAssignCluster?: (vehicle: Vehicle) => void
    onAssignTracker?: (vehicle: Vehicle) => void
    onEdit?: (vehicle: Vehicle) => void
    pagination?: {
        current: number
        lastPage: number
        total: number
    }
    onPageChange?: (page: number) => void
}

export function VehicleTable({
    data,
    isLoading,
    onAssign,
    onAssignCluster,
    onAssignTracker,
    onEdit,
    pagination,
    onPageChange
}: VehicleTableProps) {
    const columns: ColumnDef<Vehicle>[] = React.useMemo(() => [
        {
            accessorKey: 'attributes.registration_number',
            header: 'Reg. No.',
            cell: ({ row }) => <span className="font-medium text-slate-900">{row.original.attributes.registration_number}</span>,
        },
        {
            header: 'Make/Model',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="text-slate-900 capitalize">{row.original.attributes.make} {row.original.attributes.model}</span>
                    <span className="text-xs text-slate-500">{row.original.attributes.year}</span>
                </div>
            ),
        },
        {
            accessorKey: 'attributes.status',
            header: 'Status',
            cell: ({ row }) => {
                const status = row.original.attributes.status
                let variant: 'default' | 'secondary' | 'destructive' | 'outline' = 'outline'

                switch (status) {
                    case 'active':
                        variant = 'default'
                        break
                    case 'in_transit':
                        variant = 'secondary'
                        break
                    case 'maintenance':
                        variant = 'secondary'
                        break
                    case 'inactive':
                        variant = 'outline'
                        break
                }

                return (
                    <Badge variant={variant} className="capitalize py-0.5">
                        {status.replace('_', ' ')}
                    </Badge>
                )
            },
        },
        {
            header: 'Body / Fuel',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="text-xs font-medium text-slate-700">{row.original.attributes.body_type}</span>
                    <div className="flex items-center gap-1.5">
                        <span className="text-[10px] text-slate-500 uppercase">{row.original.attributes.fuel_type}</span>
                        {row.original.attributes.fuel_sensor_conversion_factor && row.original.attributes.fuel_sensor_conversion_factor > 0 && (
                            <div className="h-3.5 w-3.5 rounded-full bg-emerald-50 flex items-center justify-center border border-emerald-100" title="Fuel Monitoring Supported">
                                <Fuel className="h-2 w-2 text-emerald-600" />
                            </div>
                        )}
                    </div>
                </div>
            ),
        },
        {
            header: 'Odometer',
            cell: ({ row }) => <span className="text-sm text-slate-600">{(row.original.attributes.total_odometer ?? 0).toLocaleString()} km</span>,
        },
        {
            header: 'Cluster',
            cell: ({ row }) => {
                const cluster = row.original.relationships?.cluster?.data
                return (
                    <span className="text-xs text-slate-500 font-medium">
                        {cluster?.name || 'Unassigned'}
                    </span>
                )
            },
        },
        {
            header: 'Tracker',
            cell: ({ row }) => (
                <div className="flex flex-col">
                    <span className="text-xs text-slate-900 font-mono">
                        {row.original.attributes.tracker_id || 'No tracker'}
                    </span>
                    {row.original.attributes.device_id && (
                        <span className="text-[10px] text-slate-400">ID: {row.original.attributes.device_id}</span>
                    )}
                </div>
            ),
        },
        {
            id: 'actions',
            cell: ({ row }) => {
                const vehicle = row.original

                return (
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                            <Button variant="ghost" className="h-8 w-8 p-0">
                                <span className="sr-only">Open menu</span>
                                <MoreHorizontal className="h-4 w-4" />
                            </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                            <DropdownMenuLabel>Actions</DropdownMenuLabel>
                            <DropdownMenuItem asChild>
                                <Link href={`/vehicles/${vehicle.id}`}>
                                    <Eye className="mr-2 h-4 w-4" /> View Details
                                </Link>
                            </DropdownMenuItem>
                            <PermissionGate permission="vehicles:write">
                                <DropdownMenuItem onClick={() => onEdit?.(vehicle)}>
                                    <Edit className="mr-2 h-4 w-4" /> Edit Vehicle
                                </DropdownMenuItem>
                            </PermissionGate>
                            <DropdownMenuSeparator />
                            <PermissionGate permission="vehicles:assign">
                                <DropdownMenuItem onClick={() => onAssign?.(vehicle)}>
                                    <UserPlus className="mr-2 h-4 w-4" /> Assign Driver
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => onAssignCluster?.(vehicle)}>
                                    <LayoutGrid className="mr-2 h-4 w-4" /> Assign Cluster
                                </DropdownMenuItem>
                                <DropdownMenuItem onClick={() => onAssignTracker?.(vehicle)}>
                                    <Cpu className="mr-2 h-4 w-4" /> Assign Tracker
                                </DropdownMenuItem>
                            </PermissionGate>
                            <DropdownMenuSeparator />
                            <PermissionGate permission="vehicles:delete">
                                <DropdownMenuItem className="text-rose-600 focus:text-rose-600">
                                    <Trash2 className="mr-2 h-4 w-4" /> Delete
                                </DropdownMenuItem>
                            </PermissionGate>
                        </DropdownMenuContent>
                    </DropdownMenu>
                )
            },
        },
    ], [onAssign, onAssignCluster, onAssignTracker, onEdit])

    const table = useReactTable({
        data,
        columns,
        getCoreRowModel: getCoreRowModel(),
    })

    if (isLoading) {
        return <div className="p-8 text-center text-slate-500">Loading vehicles...</div>
    }

    return (
        <div className="space-y-4">
            <div className="rounded-md border border-slate-200 bg-white">
                <Table>
                    <TableHeader className="bg-slate-50">
                        {table.getHeaderGroups().map((headerGroup) => (
                            <TableRow key={headerGroup.id}>
                                {headerGroup.headers.map((header) => {
                                    return (
                                        <TableHead key={header.id}>
                                            {header.isPlaceholder
                                                ? null
                                                : flexRender(
                                                    header.column.columnDef.header,
                                                    header.getContext()
                                                )}
                                        </TableHead>
                                    )
                                })}
                            </TableRow>
                        ))}
                    </TableHeader>
                    <TableBody>
                        {table.getRowModel().rows?.length ? (
                            table.getRowModel().rows.map((row) => (
                                <TableRow
                                    key={row.id}
                                    data-state={row.getIsSelected() && 'selected'}
                                    className="hover:bg-slate-50/50"
                                >
                                    {row.getVisibleCells().map((cell) => (
                                        <TableCell key={cell.id}>
                                            {flexRender(cell.column.columnDef.cell, cell.getContext())}
                                        </TableCell>
                                    ))}
                                </TableRow>
                            ))
                        ) : (
                            <TableRow>
                                <TableCell colSpan={columns.length} className="h-24 text-center">
                                    No vehicles found.
                                </TableCell>
                            </TableRow>
                        )}
                    </TableBody>
                </Table>
            </div>

            {pagination && pagination.lastPage > 1 && (
                <div className="flex items-center justify-between px-2">
                    <p className="text-sm text-slate-500">
                        Showing <span className="font-medium text-slate-900">{data.length}</span> of <span className="font-medium text-slate-900">{pagination.total}</span> vehicles
                    </p>
                    <Pagination className="mx-0 w-auto">
                        <PaginationContent>
                            <PaginationItem>
                                <PaginationPrevious
                                    href="#"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        if (pagination.current > 1) onPageChange?.(pagination.current - 1);
                                    }}
                                    className={pagination.current === 1 ? "pointer-events-none opacity-50" : "cursor-pointer"}
                                />
                            </PaginationItem>

                            {/* Simple page numbers */}
                            {Array.from({ length: Math.min(5, pagination.lastPage) }, (_, i) => {
                                // Logic to show pages around current
                                let pageNum = i + 1;
                                if (pagination.lastPage > 5) {
                                    if (pagination.current > 3) {
                                        pageNum = pagination.current - 2 + i;
                                        if (pageNum > pagination.lastPage) pageNum = pagination.lastPage - 4 + i;
                                    }
                                }
                                if (pageNum <= 0) return null;
                                if (pageNum > pagination.lastPage) return null;

                                return (
                                    <PaginationItem key={pageNum}>
                                        <PaginationLink
                                            href="#"
                                            isActive={pagination.current === pageNum}
                                            onClick={(e) => {
                                                e.preventDefault();
                                                onPageChange?.(pageNum);
                                            }}
                                            className="cursor-pointer"
                                        >
                                            {pageNum}
                                        </PaginationLink>
                                    </PaginationItem>
                                )
                            })}

                            <PaginationItem>
                                <PaginationNext
                                    href="#"
                                    onClick={(e) => {
                                        e.preventDefault();
                                        if (pagination.current < pagination.lastPage) onPageChange?.(pagination.current + 1);
                                    }}
                                    className={pagination.current === pagination.lastPage ? "pointer-events-none opacity-50" : "cursor-pointer"}
                                />
                            </PaginationItem>
                        </PaginationContent>
                    </Pagination>
                </div>
            )}
        </div>
    )
}

'use client'

import { useEffect, useCallback } from 'react'
import getEcho from '@/lib/echo'

export function useEcho() {
    const echo = getEcho

    const subscribe = useCallback((channelName: string, eventName: string, callback: (data: any) => void) => {
        if (!echo) return

        const channel = echo.channel(channelName)
        channel.listen(eventName, callback)

        return () => {
            channel.stopListening(eventName)
        }
    }, [echo])

    const subscribePrivate = useCallback((channelName: string, eventName: string, callback: (data: any) => void) => {
        if (!echo) return

        const channel = echo.private(channelName)
        channel.listen(eventName, callback)

        return () => {
            channel.stopListening(eventName)
        }
    }, [echo])

    return {
        echo,
        subscribe,
        subscribePrivate
    }
}

'use client'

import { useEffect, useState } from 'react'
import { useEcho } from './useEcho'
import { useAuthStore } from '@/store/authStore'

export interface VehicleTelemetry {
    vehicle_id: string
    latitude: number
    longitude: number
    speed: number
    heading: number
    status: string
    fuel_level_percent: number
    fuel_level_liters: number
    gps_datetime: string
    address: string
    ignition: string
    movement: string
    odometer: number
    metadata?: {
        engine_rpm?: number
        engine_temperature?: number
        battery_voltage?: number
        idling?: boolean
        eco_score?: number
        [key: string]: unknown
    }
}

export function useFleetTracking() {
    const { echo } = useEcho()
    const { organization } = useAuthStore()
    const [telemetryMap, setTelemetryMap] = useState<Record<string, VehicleTelemetry>>({})
    const [alerts, setAlerts] = useState<any[]>([])

    const orgId = organization?.id

    useEffect(() => {
        if (!echo || !orgId) return

        const channel = echo.private(`location.organization.${orgId}`)

        channel.listen('.current.recent', (packet: any) => {
            setTelemetryMap(prev => ({
                ...prev,
                [packet.vehicle_id]: {
                    vehicle_id: packet.vehicle_id,
                    latitude: packet.latitude,
                    longitude: packet.longitude,
                    speed: packet.speed,
                    heading: packet.heading,
                    status: packet.status,
                    fuel_level_percent: packet.fuel_level_percent,
                    fuel_level_liters: packet.fuel_level_liters,
                    gps_datetime: packet.gps_datetime,
                    address: packet.address,
                    ignition: packet.ignition,
                    movement: packet.movement,
                    odometer: packet.odometer,
                    metadata: packet.metadata ?? undefined
                }
            }))
        })

        // Geofence alerts
        channel.listen('.geofence.monitor', (alert: any) => {
            setAlerts(prev => [alert, ...prev].slice(0, 50))
        })

        // Status changes
        echo.private(`vehicle.status.${orgId}`)
            .listen('.vehicle.status.changed', (event: any) => {
                setTelemetryMap(prev => {
                    const existing = prev[event.vehicle_id]
                    if (!existing) return prev
                    return {
                        ...prev,
                        [event.vehicle_id]: {
                            ...existing,
                            status: event.new_status
                        }
                    }
                })
            })

        return () => {
            echo.leave(`location.organization.${orgId}`)
            echo.leave(`vehicle.status.${orgId}`)
        }
    }, [echo, orgId])

    return { telemetryMap, alerts }
}

import { useSubscriptionStore, type GatedModule } from '@/store/subscriptionStore'

export function useSubscription() {
    const { hasCapability, planTier, planName, dunningStage } = useSubscriptionStore()
    const isPaymentOverdue = dunningStage === 'restricted' || dunningStage === 'suspended'
    const isGracePeriod = dunningStage === 'grace'

    return {
        hasCapability,
        hasModule: hasCapability, // Alias for backward compatibility
        planTier,
        planName,
        isPaymentOverdue,
        isGracePeriod,
        dunningStage
    }
}

'use client'

import { useEffect, useState } from 'react'
import { useEcho } from './useEcho'
import { useAuthStore } from '@/store/authStore'

export function useVehicleTelemetry(vehicleId: string | null, deviceImei?: string | null) {
    const { echo } = useEcho()
    const { organization } = useAuthStore()
    const [telemetry, setTelemetry] = useState<any>(null)
    const [deviceStatus, setDeviceStatus] = useState<string | null>(null)

    const orgId = organization?.id

    useEffect(() => {
        if (!echo || !vehicleId || !orgId) return

        // Per-vehicle location
        const vehicleChannel = echo.private(`location.vehicle.${vehicleId}`)
        vehicleChannel.listen('.current.recent', (packet: any) => {
            setTelemetry(packet)
        })

        // Fuel level
        const fuelChannel = echo.private(`fuel.vehicle.${vehicleId}`)
        fuelChannel.listen('.fuel.level', (event: any) => {
            setTelemetry((prev: any) => prev ? {
                ...prev,
                fuel_level_percent: event.fuel_level_percent,
                fuel_level_liters: event.fuel_level_liters
            } : null)
        })

        // Device status
        let statusChannel: any = null
        if (deviceImei) {
            statusChannel = echo.private(`devicestatus.${orgId}.${deviceImei}`)
            statusChannel.listen('.device.status', (event: any) => {
                setDeviceStatus(event.status)
            })
        }

        return () => {
            echo.leave(`location.vehicle.${vehicleId}`)
            echo.leave(`fuel.vehicle.${vehicleId}`)
            if (deviceImei) {
                echo.leave(`devicestatus.${orgId}.${deviceImei}`)
            }
        }
    }, [echo, vehicleId, orgId, deviceImei])

    return { telemetry, deviceStatus }
}

