import Echo from 'laravel-echo'
import Pusher from 'pusher-js'

declare global {
    interface Window {
        Pusher: any
        Echo: Echo<any>
    }
}

if (typeof window !== 'undefined') {
    window.Pusher = Pusher
}


console.log(process.env.NEXT_PUBLIC_PUSHER_HOST)

const echoConfig: any = {
    broadcaster: 'reverb',
    key: process.env.NEXT_PUBLIC_PUSHER_APP_KEY || 'your_pusher_key',
    wsHost: process.env.NEXT_PUBLIC_PUSHER_HOST || 'reverb.eonsfleet.local',
    wsPort: parseInt(process.env.NEXT_PUBLIC_PUSHER_PORT || '8080'),
    // wssPort: parseInt(process.env.NEXT_PUBLIC_PUSHER_PORT || '8080'),
    forceTLS: process.env.NEXT_PUBLIC_PUSHER_SCHEME === 'https',
    enabledTransports: ['ws', 'wss'],
    authEndpoint: process.env.NEXT_PUBLIC_PUSHER_HOST + '/broadcasting/auth',
    auth: {
        headers: {
            'X-Request-Type': 'client',
        },
    },
}

let echoInstance: Echo<any> | null = null

export const getEcho = () => {
    if (typeof window === 'undefined') return null

    if (!echoInstance) {
        const token = typeof window !== 'undefined' ? (window as any).JS_COOKIE?.get('token') : null; // Fallback or use standard logic
        echoInstance = new Echo({
            ...echoConfig,
            auth: {
                headers: {
                    ...echoConfig.auth.headers,
                    Authorization: `Bearer ${token}`,
                }
            }
        })
    }

    return echoInstance
}

export default getEcho()

import axios from 'axios'

export interface GpsPacket {
    latitude: number
    longitude: number
    speed: number
    course: number
    ignition: boolean
    movement: boolean
    fuel_level_percent: number
    fuel_level_liters: number
    odometer: number
    timestamp: string
    address?: string
    status: string
}

export const normalizeGpsPacket = (data: any): GpsPacket => {
    const location = data.location || {}
    const attributes = data.attributes || {}

    return {
        latitude: Number(location.latitude) || 0,
        longitude: Number(location.longitude) || 0,
        speed: Number(location.speed) || 0,
        course: Number(location.heading) || 0,
        ignition: location.ignition === 'on' || attributes.ignition === 'on',
        movement: location.movement === 'on' || attributes.movement === 'on',
        fuel_level_percent: Number(location.fuel_level_percent) || 0,
        fuel_level_liters: Number(location.fuel_level_liters) || 0,
        odometer: Number(location.odometer) || 0,
        timestamp: location.timestamp_utc || location.gps_datetime || new Date().toISOString(),
        address: location.address || null,
        status: location.status || data.device?.status || 'offline'
    }
}

export const reverseGeocode = async (lat: number, lng: number): Promise<string> => {
    try {
        // Using Nominatim (OpenStreetMap) for free reverse geocoding
        const response = await axios.get(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}&zoom=18&addressdetails=1`, {
            headers: {
                'User-Agent': 'Eonsfleet-Frontend/1.0'
            }
        })
        return response.data.display_name || 'Unknown Location'
    } catch (error) {
        console.error('Reverse geocoding error:', error)
        return 'Location unavailable'
    }
}

